-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
local addon_name = ...
LibStub("AceLocale-3.0"):NewLocale(addon_name, "enUS", true, true)
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.paladin.holy.Name"] = "Holy"
L["rm.era.paladin.holy.Description"] = "Healing in a group with the Holy tree, from level 10. Acts on your friendly target and picks the heal by missing health: Cleanse or Purify, Holy Shock while you move, maximum-rank Holy Light below 40%, rank-6 Holy Light below 65%, maximum-rank Flash of Light below 85%, rank-4 Flash of Light below 95%. With an enemy in melee range: Seal of Wisdom and, outside raids, Judgement. Reminders: Concentration or Devotion Aura, Blessing of Wisdom, Divine Favor and Lay on Hands for a target that is very low. Choosing whom to heal stays with you; soloing Holy Paladins get the Retribution premade."
L["rm.era.paladin.protection.Name"] = "Protection"
L["rm.era.paladin.protection.Description"] = "Tanking from level 1 to 60, chosen by Righteous Fury or the Protection tree. Seal of Righteousness (Seal of Wisdom when mana drops below 40%), Holy Shield and Judgement to pull, Holy Shield kept up, Consecration and Holy Wrath (Undead and Demons) when two or more enemies are on you, otherwise Judgement of the Crusader once, then Judgement and Consecration with mana to spare, Exorcism on Undead and Demons. Reminders: Righteous Fury, Devotion Aura, Sanctuary, Kings or Might, Lay on Hands when nearly dead. Taunting, Blessing of Kings spam and spell ranks stay with you."
L["rm.era.paladin.protection.icyveins.Name"] = "Protection, Seal of Wisdom (Icy Veins)"
L["rm.era.paladin.protection.icyveins.Description"] = "Icy Veins' raid tanking with Wowhead's Wisdom rotation, an alternative to the recommended Protection premade, off by default: enable it and disable that one, or raise its priority. Keeps Seal of Wisdom up and judges it whenever the target lacks Judgement of Wisdom, otherwise judges only to pull; Holy Shield, Consecration every cooldown, Holy Wrath on Undead and Demon packs, Exorcism, and Greater Blessing of Kings as the threat filler in a raid. Same reminders as the recommended premade."
L["rm.era.paladin.retribution.Name"] = "Retribution"
L["rm.era.paladin.retribution.Description"] = "Melee Retribution from level 1 to 60, and the default for any Paladin no other premade fits. On elites and long fights outside raids, puts up Seal of the Crusader and judges it once; otherwise keeps a seal up (Command with a weapon of 3.5 seconds or slower, else Righteousness), Exorcism and Holy Wrath on Undead and Demons, Hammer of Wrath, Judgement on cooldown, Consecration while Vengeance is up or on two or more close enemies. Reminders: Sanctity, Retribution or Devotion Aura, Blessing of Wisdom solo or Might in a group, a heal between fights, Divine Shield, Divine Protection or Lay on Hands when you are about to die. Seal twisting is a separate premade; target choice and positioning stay with you."
L["rm.era.paladin.retribution.twist.Name"] = "Retribution, seal twisting"
L["rm.era.paladin.retribution.twist.Description"] = "Off by default; enable it if you twist seals. For a Retribution Paladin with Seal of Command: keeps Seal of Righteousness up, swaps to rank-1 Seal of Command in the last 0.4 seconds before a swing and back again, Judgement whenever it is ready, Exorcism and Holy Wrath on Undead and Demons, Hammer of Wrath, Consecration with Vengeance. Needs a lot of mana and good timing. Same reminders as the Retribution premade."
L["rm.forever.paladin.holy.Name"] = "Holy"
L["rm.forever.paladin.holy.Description"] = "Group healing once Holy is your main talent tree with 21 points (Holy Shock's tier), while Righteous Fury is off (a grouped Shockadin lands here too). Heals your current friendly target: Holy Shock on a target with your Light's Vigil, Light's Vigil in combat, Cleanse or Purify, Holy Shock while moving, Holy Light with Infusion of Light, Flash of Light as the main heal. On an enemy: Judgement of Light when Seal of Light is up, Holy Shock, Light's Vigil, Holy Strike, Exorcism. Reminders: Seal of Light when you have no seal, Divine Favor in combat on a friendly target, your aura and Blessing. Health and mana are hidden from addons on Forever, so the target you pick is the only sign of who needs healing; emergency Holy Shocks, big Holy Lights and Lay on Hands are your call."
L["rm.forever.paladin.holy.wowhead.Name"] = "Holy, Holy Shock on cooldown (Wowhead)"
L["rm.forever.paladin.holy.wowhead.Description"] = "Wowhead's healing style, an alternative to the recommended Holy premade, off by default: enable it and disable that one, or raise its priority. Holy Shock as a routine heal on cooldown, dispels, Flash of Light (health is hidden on Forever, so Holy Light for big deficits is your call). On an enemy it keeps your Judgement of Light up by swapping to Seal of Light, judging and swapping back to Seal of Righteousness, then Holy Strike, Exorcism on Undead and Demons, Holy Shock and Consecration. Same reminders as the Holy premade."
L["rm.forever.paladin.protection.Name"] = "Protection (Wowhead)"
L["rm.forever.paladin.protection.Description"] = "Tanking, once Protection is your main talent tree or you turn on Righteous Fury. When the target is fighting someone else: Judgement with Seal of Fury (the taunt), Swift Judgement to reset it. Two or more enemies engaged: Consecration, Exorcism and Holy Wrath on Undead and Demons, Holy Strike. One enemy: Exorcism on Undead and Demons, Holy Strike, Consecration. Reminders: Righteous Fury, Seal of Fury, Judgement on cooldown, Holy Shield while tanking, your aura and Blessing. Health and mana are hidden from addons on Forever, so Templar's Bulwark and Lay on Hands are your call. Pulling, positioning and other taunts stay with you."
L["rm.forever.paladin.protection.icyveins.Name"] = "Protection, Consecration first (Icy Veins)"
L["rm.forever.paladin.protection.icyveins.Description"] = "Icy Veins' tanking style, an alternative to the recommended Wowhead Protection premade, off by default: enable it and disable that one, or raise its priority. Consecration first whenever you can afford it, on one enemy too; Judgement is kept for taunts (no on-cooldown reminder), with Swift Judgement to reset it; then Holy Strike and Exorcism on Undead and Demons. Same tank reminders otherwise."
L["rm.forever.paladin.retribution.Name"] = "Retribution"
L["rm.forever.paladin.retribution.Description"] = "Retribution and every melee Paladin from level 1 to 60, and the Forever Paladin default. Keeps a damage seal up, refreshed only when it runs low: Seal of the Crusader judged once on an elite target, then Seal of Command with a slow (3.0 s) weapon, else Seal of Righteousness. Then Holy Strike on cooldown, Holy Shock and Light's Vigil for a Shockadin, Exorcism on Undead and Demons, Consecration on three or more enemies, Hammer of Wrath when it can be cast, and melee. Judgement is off the global cooldown, so it is a reminder whenever a seal is up. Other reminders: your aura and Blessing (Retribution Aura and Kings once learned; yours are kept). Optional step, off by default: Hammer of Justice before a Seal of Command Judgement. Mana, health and the swing timer are hidden from addons on Forever, so mana saving, healing yourself, Lay on Hands and Twist of Light seal swapping are your call. Built from level-30 beta guides."
L["rm.mop.paladin.holy.Name"] = "Recommended"
L["rm.mop.paladin.holy.Description"] = "For Holy, from level 10 in the Holy specialization. With a friend targeted it heals: at 3 Holy Power (or Divine Purpose) Light of Dawn when three people near you are hurt, else Eternal Flame on a target without it, else Word of Glory; Holy Shock on cooldown; Infusion of Light into Holy Radiance or Divine Light, three Selfless Healer stacks into Holy Radiance or Flash of Light; Flash of Light below 35%; Holy Radiance for a hurt group; Divine Light, then Holy Light to top off. With an enemy targeted it deals damage: Holy Shock, Judgment, Crusader Strike, Holy Prism, Execution Sentence, Hammer of Wrath, Denounce. Reminders: Seal of Insight when another seal (except Righteousness) or none is active, blessings, Rebuke, Beacon of Light and Sacred Shield on your focus (set the tank as focus), Divine Plea below 60% mana, Light's Hammer and your healing cooldowns when three people are below 70%, Lay on Hands on a dying target. Choosing whom to heal, dispels and mouseover healing stay with you."
L["rm.mop.paladin.protection.Name"] = "Recommended"
L["rm.mop.paladin.protection.Description"] = "Recommended for Protection, from level 10 in the Protection specialization. Pulls with Avenger's Shield, then Avenger's Shield on a Grand Crusader proc, Avenger's Shield, Hammer of Wrath, Crusader Strike, Judgment, your level-90 talent, Consecration, Holy Wrath and Sacred Shield. Three or more enemies on you switch to Avenger's Shield, Consecration, Hammer of the Righteous, Judgment and Holy Wrath. Shield of the Righteous, Eternal Flame and Word of Glory are off the global cooldown, so they light beside the rotation: Shield of the Righteous whenever you can afford it, Eternal Flame on yourself when it is running out with 3 Holy Power and three Bastion of Glory stacks, Word of Glory below half health without that talent. Other reminders: Righteous Fury, Seal of Insight when another seal (except Righteousness) or none is active, blessings, Rebuke, Sacred Shield, Avenging Wrath and Holy Avenger while you are tanking, and Guardian of Ancient Kings, Ardent Defender, Divine Protection and Lay on Hands by your health. It cannot see incoming damage, so plan big defensives yourself."
L["rm.mop.paladin.protection.simulator.Name"] = "Pool Holy Power (simulator)"
L["rm.mop.paladin.protection.simulator.Description"] = "An alternative to the recommended Protection premade, off by default: enable it and disable that one, or raise its priority. Follows the simulator's tank lists: Shield of the Righteous waits for full Holy Power unless you fall below 40% health or Divine Purpose makes it free; Eternal Flame just before it fades with more than two Bastion of Glory stacks; Sacred Shield kept up; Holy Avenger and Avenging Wrath on cooldown. Generators run Crusader Strike, Judgment, then Avenger's Shield, Holy Wrath, the level-90 talent and Hammer of Wrath, with the same three-enemy AoE order. Boss-timed defensives are yours."
L["rm.mop.paladin.retribution.Name"] = "Recommended"
L["rm.mop.paladin.retribution.Description"] = "Recommended for Retribution, from level 10 in the Retribution specialization. Keeps Inquisition up (cast at 3 Holy Power, refreshed in its last 3 seconds; from 81), spends Templar's Verdict at full Holy Power or on a free proc before generating more, then Hammer of Wrath, Crusader Strike, Judgment and Exorcism, and Templar's Verdict at 3 when nothing else is ready. In Avenging Wrath it spends at once and puts Judgment ahead of Crusader Strike. Two or more enemies on you switch to Divine Storm, with Hammer of the Righteous when four are close. Pulls from range with Judgment or Exorcism, and suggests Word of Glory when you are solo and in danger. Reminders: Seal of Truth when another seal is active or none (Seal of Righteousness is kept), Blessing of Kings or Might, Rebuke, Avenging Wrath and Guardian of Ancient Kings with Inquisition up on elites, Holy Avenger in wings, Execution Sentence and Light's Hammer, and Divine Protection and Lay on Hands when low. Seal of Righteousness for packs and glyph choices stay with you."
L["rm.mop.paladin.retribution.warcrafttavern.Name"] = "Exorcism first (Warcraft Tavern)"
L["rm.mop.paladin.retribution.warcrafttavern.Description"] = "An alternative to the recommended Retribution premade, off by default: enable it and disable that one, or raise its priority. Exorcism on every cooldown and Art of War reset comes first; Inquisition is cast at any Holy Power when it is missing and refreshed at 3 in its last 20 seconds; then Crusader Strike, Judgment, Templar's Verdict and Hammer of Wrath (first in wings with Sanctified Wrath). Two or more enemies use Crusader Strike, Light's Hammer, Judgment, Divine Storm and Hammer of Wrath. Avenging Wrath and Guardian of Ancient Kings are suggested only on elites. The guide's Seal of Righteousness on any cleave is left to you."
L["rm.mop.paladin.unspecialized.Name"] = "Before a specialization"
L["rm.mop.paladin.unspecialized.Description"] = "For levels 1 to 9, and any paladin who has not chosen a specialization yet; a specialization's premade takes over as soon as you pick one. Pulls from range with Judgment, then Crusader Strike and Judgment, with Hammer of Justice when you are solo and below half health and Word of Glory below 40%. Reminders: Seal of Command (Seal of Truth from 24) when you are not in it, Blessing of Kings, Rebuke, and Flash of Light out of combat when you are hurt."
L["rm.retail.paladin.holy.Name"] = "Icy Veins"
L["rm.retail.paladin.holy.Description"] = "Holy in Midnight, for reference: Rotation Master picks a spell, not a target, and the game hides everyone's health in combat, so this keeps your Holy Power and cooldowns turning over on whatever you target and leaves deciding who needs healing to you. Holy Power stays visible in combat, so it is spent at 5 first and at 3 or more after your other heals. On a friendly target: Eternal Flame or Word of Glory at 5 Holy Power, Flash of Light on Infusion of Light, Holy Shock, Eternal Flame or Word of Glory at 3 or more, Holy Light, Flash of Light; Light of Dawn is left to you. On an enemy: Shield of the Righteous at 5 Holy Power, Holy Shock, Shield of the Righteous at 3 or more, Judgment, Crusader Strike, Consecration. Reminders in combat: Divine Toll, Holy Prism, Holy Bulwark or Sacred Weapon, Beacon of Virtue on a friendly target, Divine Protection; an aura between pulls; Rebuke. Lay on Hands is left to you. Avenging Wrath and Aura Mastery are left to you."
L["rm.retail.paladin.initial.Name"] = "Blizzard Assisted"
L["rm.retail.paladin.initial.Description"] = "Recommended before you choose a specialization (while the game reports the Paladin's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, the reminders every Paladin premade shares, each once you know its spell. When you choose a specialization at level 10, that specialization's premades take over."
L["rm.retail.paladin.protection.Name"] = "Blizzard Assisted"
L["rm.retail.paladin.protection.Description"] = "Recommended for Protection in Midnight. Shows Blizzard's Assisted Combat suggestion, which already includes Shield of the Righteous, Avenging Wrath and Sentinel, and stops while you cast or have no enemy targeted. Reminders for what it leaves out: an aura between pulls, Rebuke on an interruptible cast, and Ardent Defender and Guardian of Ancient Kings whenever they are ready in combat. Health is hidden on Retail, so when to use them, and Lay on Hands, is your call. Taunting and positioning stay with you."
L["rm.retail.paladin.protection.icyveins.Name"] = "Reference (Icy Veins)"
L["rm.retail.paladin.protection.icyveins.Description"] = "Reference only, off by default: the Icy Veins and SimulationCraft order needs the Consecration, Vanguard and Shining Light buffs, which Midnight hides in combat. Consecration before the pull; then Divine Toll, Hammer of Light, Consecration when you are not standing in it, Avenger's Shield with Vanguard, Shield of the Righteous at 3 or more Holy Power, Hammer of Wrath, Judgment, Blessed Hammer or Hammer of the Righteous, Avenger's Shield, Word of Glory with Shining Light, Consecration. Reminders: Avenging Wrath or Sentinel, Holy Bulwark, Sacred Weapon outside Avenging Wrath, defensives, aura, Rebuke."
L["rm.retail.paladin.protection.wowhead.Name"] = "Consecration filler reference (Wowhead)"
L["rm.retail.paladin.protection.wowhead.Description"] = "Reference only, off by default: Wowhead's tank order. Judgment on cooldown, Shield of the Righteous, Avenger's Shield, Divine Toll at 0 Holy Power, Blessed Hammer or Hammer of the Righteous, and Consecration only as the filler. Health is hidden on Retail, so Word of Glory below half health is left to you. Same reminders as the Icy Veins reference."
L["rm.retail.paladin.retribution.Name"] = "Blizzard Assisted"
L["rm.retail.paladin.retribution.Description"] = "Recommended for Retribution in Midnight. In combat the game now hides buffs, debuffs, cooldown times and health from addons, so this shows Blizzard's own Assisted Combat suggestion (the one-button rotation) on your action bars, and stops while you cast or have no enemy targeted. It also reminds you of what that suggestion never covers: an aura between pulls, Rebuke on an interruptible cast, and Divine Protection whenever it is ready in combat. Health is hidden on Retail, so when to use Divine Protection and Lay on Hands is your call. Trinkets and racials stay with you."
L["rm.retail.paladin.retribution.icyveins.Name"] = "Reference (Icy Veins)"
L["rm.retail.paladin.retribution.icyveins.Description"] = "Reference only, off by default: the Icy Veins and SimulationCraft order reads buffs, charges and enemy counts that Midnight hides in combat, so it cannot run reliably there. Hammer of Light; a free Divine Purpose spender; at 5 Holy Power while Wake of Ashes is cooling, the spender; Wake of Ashes; Divine Toll; Blade of Justice on Art of War; Hammer of Wrath before it caps; at 3 or more Holy Power, Divine Storm on two or more enemies (or with Empyrean Power), else Final Verdict; Hammer of Wrath; Blade of Justice; Judgment; Templar Strike or Crusader Strike. Holy Power stays visible in combat, so its spending points work there. Reminders: Avenging Wrath, Execution Sentence with Wake of Ashes ready, aura, Rebuke, defensives."
L["rm.sod.paladin.holy.Name"] = "Holy (SoD)"
L["rm.sod.paladin.holy.Description"] = "Season of Discovery healing in a group, chosen by an engraved Beacon of Light, Divine Light or Sacred Shield, or the Holy tree without Crusader Strike. Acts on your friendly target: Cleanse, Holy Shock while moving or below 30%, Divine Light (Holy Light when mana is under half) below 60%, Flash of Light below 90%. With an enemy in melee range it only keeps a seal up. Reminders: Beacon of Light and Sacred Shield on the target that lacks them, Concentration or Devotion Aura, Blessing of Wisdom, Divine Favor and Lay on Hands for a target that is very low. The guides behind it are from Phase 4; choosing whom to heal stays with you."
L["rm.sod.paladin.holy.wowhead.Name"] = "Holy, Holy Light first (SoD, Wowhead)"
L["rm.sod.paladin.holy.wowhead.Description"] = "Wowhead's Phase 4 healing order for crit-heavy gear, an alternative to the recommended Season of Discovery Holy premade, off by default: enable it and disable that one, or raise its priority. Divine Light or Holy Light below 75%, then Cleanse, Holy Shock for small deficits or while moving, Flash of Light below 95%. Same reminders as the recommended premade."
L["rm.sod.paladin.protection.Name"] = "Protection (SoD)"
L["rm.sod.paladin.protection.Description"] = "Season of Discovery tanking, chosen by Righteous Fury, an engraved Hammer of the Righteous or Shield of Righteousness, or the Protection tree. Seal of Martyrdom, a pull with Holy Shield, Avenger's Shield and Exorcism, Holy Shield kept up; on one target Hammer of the Righteous, Shield of Righteousness, Exorcism, Avenger's Shield, Judgement, Divine Storm, Consecration; with three or more enemies on you Hammer of the Righteous, Avenger's Shield, Consecration, Shield of Righteousness, Exorcism. Reminders: Righteous Fury, Holy Shield before a pull, Devotion Aura, Sanctuary or Kings, Avenging Wrath, Divine Protection below 40%, Lay on Hands, Hand of Reckoning in a group when your target attacks someone else."
L["rm.sod.paladin.protection.simulator.Name"] = "Protection (SoD, simulator)"
L["rm.sod.paladin.protection.simulator.Description"] = "The simulator tank list, an alternative to the recommended Season of Discovery Protection premade, off by default: enable it and disable that one, or raise its priority. Judgement whenever a seal is up, the seal renewed just before it runs out, Holy Shield, Avenger's Shield, Hammer of the Righteous, Exorcism, Shield of Righteousness last. Same reminders as the recommended premade."
L["rm.sod.paladin.retribution.Name"] = "Retribution (SoD)"
L["rm.sod.paladin.retribution.Description"] = "Season of Discovery melee from level 1 to 60, and the default for any Paladin there. Keeps Seal of Martyrdom up (Righteousness until you have it), opens with Exorcism, casts Divine Storm at three Holy Power, then by weapon speed: with a two-hander of 3.3 seconds or slower, Crusader Strike, Exorcism, Divine Storm and Judgement; with a faster one, Judgement only as the seal runs out, then Exorcism, Crusader Strike and Divine Storm. Consecration with mana or three close enemies, Holy Wrath on Undead and Demons (on anything with Purifying Power engraved), Hammer of Wrath with mana to spare (always with Improved Hammer of Wrath engraved). Runes are used as you engrave them. Reminders: Sanctity Aura, a Blessing, Avenging Wrath with Aura Mastery, a heal between fights, Divine Shield when about to die."
L["rm.sod.paladin.retribution.icyveins.Name"] = "Retribution (SoD, Icy Veins Phase 4)"
L["rm.sod.paladin.retribution.icyveins.Description"] = "The older Phase 4 list from Icy Veins and Warcraft Tavern, also fine for leveling, an alternative to the recommended Season of Discovery Retribution premade, off by default: enable it and disable that one, or raise its priority. Judgement of the Crusader once on elites and long fights, Seal of Martyrdom, Exorcism, Crusader Strike, Divine Storm and Judgement on cooldown, Consecration with mana or three close enemies, Hammer of Wrath. Same reminders as the recommended premade."
L["rm.sod.paladin.retribution.stacking.Name"] = "Retribution, seal stacking (SoD)"
L["rm.sod.paladin.retribution.stacking.Description"] = "Off by default; enable it with the Soul of the Sealbearer rune or the six-piece set that makes seals linger (Rotation Master cannot see either). Keeps both Seal of Command and Seal of Martyrdom up, Divine Storm at three Holy Power, Crusader Strike, Exorcism, Holy Wrath on Undead and Demons (on anything with Purifying Power engraved), Consecration, and Judgement while both seals are up."
L["rm.sod.paladin.retribution.twist.Name"] = "Retribution, seal twisting (SoD)"
L["rm.sod.paladin.retribution.twist.Description"] = "Off by default; enable it if you twist with a slow two-hander. Swaps between Seal of Martyrdom and Seal of Command in the last 0.4 seconds before each swing, suggests nothing on the global cooldown in the 1.9 seconds before it, judges while both seals linger, and uses one filler per swing: Divine Storm at three Holy Power, Crusader Strike, Exorcism. Needs a swing timer and practice."
L["rm.sod.paladin.shockadin.Name"] = "Shockadin (SoD, simulator)"
L["rm.sod.paladin.shockadin.Description"] = "Off by default; enable it if you deal damage with the Holy tree. It applies with Holy as your main tree and Shock and Awe engraved. Seal of Martyrdom (else Righteousness), judged as it runs out, Holy Shock to keep Sunlight up or at three Holy Power, Exorcism and Crusader Strike. Same reminders as the Season of Discovery Retribution premade."
L["rm.tbc.paladin.holy.Name"] = "Holy (Icy Veins & Wowhead)"
L["rm.tbc.paladin.holy.Description"] = "Healing for a Holy Paladin in a group, on your friendly target: Lay on Hands or Holy Shock for a dying target, Cleanse (Purify before 42), Holy Shock while moving, Holy Light for heavy damage, rank-5 Holy Light to keep Light's Grace up, Flash of Light otherwise. With a hostile target it keeps Judgement of Wisdom up. Reminders: Concentration Aura, Blessing of Wisdom, Divine Illumination and Divine Favor. A soloing Holy Paladin gets a Retribution premade instead."
L["rm.tbc.paladin.holy.wowhead.Name"] = "Holy (Wowhead tank healing)"
L["rm.tbc.paladin.holy.wowhead.Description"] = "Wowhead's raid tank healing, an alternative to the recommended Holy premade, off by default: enable it and disable that one, or raise its priority. Holy Light whenever your target is missing a tenth of their health, Flash of Light only for small deficits, with the same emergencies, cleansing, Judgement and reminders as the blended Holy premade."
L["rm.tbc.paladin.protection.icyveins.Name"] = "Protection (Icy Veins)"
L["rm.tbc.paladin.protection.icyveins.Description"] = "Icy Veins' tanking, an alternative to the recommended Wowhead Protection premade, off by default: enable it and disable that one, or raise its priority. Judgement of the Crusader when nobody keeps it up, Righteousness (Wisdom on packs), Consecration as the main threat, Judgement, Holy Shield, then Avenger's Shield and Hammer of Wrath on cooldown. Same reminders as the Wowhead variant without Avenging Wrath."
L["rm.tbc.paladin.protection.wowhead.Name"] = "Protection (Wowhead & simulator)"
L["rm.tbc.paladin.protection.wowhead.Description"] = "Tanking for the Protection tree or any Paladin with Righteous Fury on. Pulls with Holy Shield, Avenger's Shield and Judgement; against a crushing target (world boss or three or more levels above you) Holy Shield comes first; then Consecration, Exorcism on Undead and Demons, Judgement, Holy Shield, Holy Wrath on undead packs, Avenger's Shield except on crushing targets. Seal of Wisdom on packs when mana is short, Righteousness otherwise. Reminders: Righteous Fury, Devotion Aura, Sanctuary (or Kings, or Wisdom), Avenging Wrath, Lay on Hands. Taunts and target swaps stay with you."
L["rm.tbc.paladin.retribution.icyveins.Name"] = "Retribution (Icy Veins)"
L["rm.tbc.paladin.retribution.icyveins.Description"] = "Icy Veins' Retribution, an alternative to the recommended Wowhead Retribution premade, off by default: enable it and disable that one, or raise its priority. Judgement of the Crusader once per target, Seal of Righteousness (Command only with a slow weapon, Blood or Martyr once learned), Crusader Strike, Hammer of Wrath and Judgement on cooldown, Consecration on two or more enemies, Exorcism on Undead and Demons, and Holy Shock for Holy levelers. Same reminders as the Wowhead variant."
L["rm.tbc.paladin.retribution.twist.Name"] = "Retribution seal twisting"
L["rm.tbc.paladin.retribution.twist.Description"] = "Off by default; enable it if you twist seals (level 64+, Seal of Command and Blood or Martyr). Opens with Judgement of the Crusader, then each swing puts up Seal of Command (rank 1) early and switches to Blood or Martyr in the last 0.4 seconds, Crusader Strike between twists, judges only Blood or Martyr, Exorcism and Consecration only as fillers, and rolls Blood without twisting below 12% mana. Needs a reliable swing timer; latency is not accounted for."
L["rm.tbc.paladin.retribution.wowhead.Name"] = "Retribution (Wowhead & simulator)"
L["rm.tbc.paladin.retribution.wowhead.Description"] = "Melee Retribution from level 1 to 70, and the default for any Paladin no other premade fits. Opens each target with Judgement of Wisdom (low mana) or the Crusader, keeps your best seal up (Blood or Martyr, Command, then Righteousness), Crusader Strike, judges only Righteousness, Blood or Martyr (or Command on a stunned target), Exorcism on Undead and Demons, Consecration for three or more enemies with mana to spare. Hammer of Wrath is left to you (Wowhead uses it only on fleeing targets). Reminders: Sanctity, Retribution or Devotion Aura, a Blessing on yourself, a heal after the fight, Avenging Wrath. Seal twisting is a separate premade."
